export function getMacroMatrixData(indicator: string, year: number) {
  // Always evaluate all 12 calendar months for standard annual cycle matrix
  const months = Array.from({ length: 12 }).map((_, i) => `${year}-${(i + 1).toString().padStart(2, '0')}`);

  const indData = MASTER_MACRO_DATABASE[indicator] || {};

  return COUNTRIES.map((c) => {
    let countryMonths = indData[c.country] || {};
    if (Object.keys(countryMonths).length === 0 && c.country === "USA") {
      countryMonths = indData["United States"] || {};
    }

    // Determine cutoff for official publication in 2026
    const cutoffDef = OFFICIAL_RELEASE_CUTOFFS[indicator];
    const cutoff = typeof cutoffDef === "function" ? cutoffDef(c.country) : (cutoffDef || "2026-09");

    return {
      ...c,
      data: months.map((m) => {
        const raw = countryMonths[m];
        if (raw === undefined || raw === null) {
          return {
            value: null,
            status: "missing" as const
          };
        }

        // Formatting based on indicator
        const formattedVal = String(raw);

        // For historical years (2025 and earlier), all data is settled official release
        if (year < SYSTEM_CURRENT_YEAR) {
          return {
            value: formattedVal,
            status: "published" as const
          };
        }

        // For live system year (2026):
        // If release month is before or on cutoff, it is officially published!
        // If release month is beyond cutoff, it is a Trading Economics forecast!
        const isOfficial = m <= cutoff;

        return {
          value: formattedVal,
          status: isOfficial ? ("published" as const) : ("forecast" as const)
        };
      })
    };
  });
}

